package com.acme.ems.service;
import com.acme.ems.dto.EmployeeDtos.EmployeeRequest;import com.acme.ems.model.*;import com.acme.ems.repository.EmployeeRepository;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.LocalDate;import java.util.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)
class EmployeeAuditTest{
 @Mock EmployeeRepository repo;@Mock PasswordEncoder encoder;@Mock AuditService audit;@Mock LeaveBalanceService balances;EmployeeService service;Employee actor,employee,manager;
 @BeforeEach void setup(){service=new EmployeeService(repo,encoder,audit,balances);actor=user(1L,"Admin",Role.ADMIN);employee=user(2L,"Emma",Role.EMPLOYEE);manager=user(3L,"Sarah",Role.MANAGER);lenient().when(repo.findByEmailIgnoreCase(actor.getEmail())).thenReturn(Optional.of(actor));lenient().when(repo.findById(2L)).thenReturn(Optional.of(employee));lenient().when(repo.findById(3L)).thenReturn(Optional.of(manager));lenient().when(repo.findAll()).thenReturn(List.of(actor,employee,manager));lenient().when(repo.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void employeeUpdateCreatesAuditEvent(){EmployeeRequest r=new EmployeeRequest(employee.getEmployeeId(),"Emma","Updated","emma.updated@x.com",null,"Designer","Design",Role.EMPLOYEE,null,employee.getDateOfJoining());service.update(2L,r,actor.getEmail());verify(audit).record(eq(actor),eq(AuditAction.EMPLOYEE_UPDATED),eq("Employee"),eq(2L),anyString());}
 @Test void managerChangeCreatesAuditEvent(){service.changeManager(2L,3L,actor.getEmail());verify(audit).record(eq(actor),eq(AuditAction.MANAGER_CHANGED),eq("Employee"),eq(2L),contains("Sarah"));}
 private Employee user(Long id,String first,Role role){Employee e=new Employee();e.setId(id);e.setEmployeeId("E"+id);e.setFirstName(first);e.setLastName("User");e.setEmail(first.toLowerCase()+"@x.com");e.setPasswordHash("hash");e.setJobTitle("Role");e.setDepartment("Dept");e.setRole(role);e.setDateOfJoining(LocalDate.of(2024,1,1));e.setActive(true);return e;}
}
